    // ['before' => "恶耗", 'after' => "噩耗"],
    // ['before' => "耶诞", 'after' => "圣诞"],
    // ['before' => "转捩", 'after' => "转折"], // 除了专门术语，比较少见转捩的写法，大部分情况下都同转折
    // ['before' => "笑咪咪", 'after' => "笑眯眯"],
    // ['before' => "所着", 'after' => "所著"],
    // ['before' => "着作", 'after' => "著作"],
