    // ['before' => "公厘", 'after' => "毫米"],
    //
    // 不少的“卯”应改为“铆”
    // 不少的“等”可以改成“级”，如“升等”“降等”“第×等”之类的，特别是在游戏、异世界之类的主题里
    // 不少的“档案”可以改成“文件”或者“存档”，香港的文本中还会出现单个字的“档”，也是 File 的意思
    // 一日一(?![夜练]) 改为 一旦 竖排文字误识别
    // (?<![姓])沈(?![家府省市县区政世雪姑娘女]|先生|小姐|叔叔|阿姨|大人|老爷) 改为 沉
